using Contoso.Pricing;

namespace Contoso.Pricing.Tests;

[TestClass]
public sealed class PriceCalculatorTests
{
    private PriceCalculator _calculator = null!;

    [TestInitialize]
    public void Setup() => _calculator = new PriceCalculator();

    // ───────────────────────────────────────────────
    // CalculateTotal – happy-path with [DataRow]
    // ───────────────────────────────────────────────

    [TestMethod]
    [DataRow(10.00, 1, 0.0,  10.00,  DisplayName = "Single item, no tax")]
    [DataRow(10.00, 2, 0.0,  20.00,  DisplayName = "Two items, no tax")]
    [DataRow(10.00, 1, 0.10, 11.00,  DisplayName = "Single item, 10% tax")]
    [DataRow(25.50, 3, 0.08, 82.62,  DisplayName = "Fractional price, 8% tax")]
    [DataRow(0.00,  5, 0.20, 0.00,   DisplayName = "Zero price yields zero")]
    [DataRow(99.99, 0, 0.15, 0.00,   DisplayName = "Zero quantity yields zero")]
    public void CalculateTotal_ReturnsExpected(
        double unitPrice, int quantity, double taxRate, double expected)
    {
        var result = _calculator.CalculateTotal((decimal)unitPrice, quantity, (decimal)taxRate);

        Assert.AreEqual((decimal)expected, result);
    }

    // ───────────────────────────────────────────────
    // CalculateTotal – boundary / error cases
    // ───────────────────────────────────────────────

    [TestMethod]
    [DataRow(-1.00, 1, 0.0,  DisplayName = "Negative unit price throws")]
    public void CalculateTotal_NegativePrice_Throws(
        double unitPrice, int quantity, double taxRate)
    {
        Assert.ThrowsException<ArgumentOutOfRangeException>(
            () => _calculator.CalculateTotal((decimal)unitPrice, quantity, (decimal)taxRate));
    }

    [TestMethod]
    [DataRow(10.00, -1, 0.0, DisplayName = "Negative quantity throws")]
    public void CalculateTotal_NegativeQuantity_Throws(
        double unitPrice, int quantity, double taxRate)
    {
        Assert.ThrowsException<ArgumentOutOfRangeException>(
            () => _calculator.CalculateTotal((decimal)unitPrice, quantity, (decimal)taxRate));
    }

    [TestMethod]
    [DataRow(10.00, 1, -0.01, DisplayName = "Tax rate below 0 throws")]
    [DataRow(10.00, 1,  1.01, DisplayName = "Tax rate above 1 throws")]
    public void CalculateTotal_InvalidTaxRate_Throws(
        double unitPrice, int quantity, double taxRate)
    {
        Assert.ThrowsException<ArgumentOutOfRangeException>(
            () => _calculator.CalculateTotal((decimal)unitPrice, quantity, (decimal)taxRate));
    }

    // ───────────────────────────────────────────────
    // ApplyDiscount – [DynamicData] with method source
    // ───────────────────────────────────────────────

    public static IEnumerable<object[]> DiscountCases
    {
        get
        {
            yield return new object[] { 100.00m, 0m,   100.00m };  // no discount
            yield return new object[] { 100.00m, 10m,  90.00m };   // 10% off
            yield return new object[] { 100.00m, 50m,  50.00m };   // half off
            yield return new object[] { 100.00m, 100m, 0.00m };    // free
            yield return new object[] { 59.99m,  25m,  44.9925m }; // fractional result
            yield return new object[] { 0.00m,   50m,  0.00m };    // zero price
        }
    }

    [TestMethod]
    [DynamicData(nameof(DiscountCases))]
    public void ApplyDiscount_ReturnsExpected(
        decimal price, decimal discountPercent, decimal expected)
    {
        var result = _calculator.ApplyDiscount(price, discountPercent);

        Assert.AreEqual(expected, result);
    }

    // ───────────────────────────────────────────────
    // ApplyDiscount – error cases via [DynamicData] method
    // ───────────────────────────────────────────────

    public static IEnumerable<object[]> InvalidDiscountCases()
    {
        yield return new object[] { 100.00m, -1m };
        yield return new object[] { 100.00m, 100.01m };
        yield return new object[] { 50.00m,  -0.01m };
    }

    [TestMethod]
    [DynamicData(nameof(InvalidDiscountCases), DynamicDataSourceType.Method)]
    public void ApplyDiscount_InvalidPercent_Throws(
        decimal price, decimal discountPercent)
    {
        Assert.ThrowsException<ArgumentOutOfRangeException>(
            () => _calculator.ApplyDiscount(price, discountPercent));
    }

    // ───────────────────────────────────────────────
    // FormatPrice – quick [DataRow] coverage
    // ───────────────────────────────────────────────

    [TestMethod]
    [DataRow(19.99,  "$",  "$19.99",  DisplayName = "USD format")]
    [DataRow(19.99,  "€",  "€19.99",  DisplayName = "EUR format")]
    [DataRow(1000.5, "$",  "$1000.50", DisplayName = "Pads to two decimals")]
    [DataRow(0.0,    "£",  "£0.00",   DisplayName = "Zero in GBP")]
    public void FormatPrice_ReturnsExpected(
        double price, string symbol, string expected)
    {
        var result = _calculator.FormatPrice((decimal)price, symbol);

        Assert.AreEqual(expected, result);
    }
}

